<script lang="ts">
 import {onMount,onDestroy,tick,untrack} from 'svelte';
 import {surface} from './surfaces';
 import {deviceSync,type SyncStatus} from '../sync/session';
 import {parseInvitation} from '../sync/crypto';
 import {canonical,key,type SyncRecord} from '../sync/records';
 import type {Core} from '../core/core';
 import type {SQLiteAdapter} from '../storage/adapter';
 import type QrScanner from 'qr-scanner';
 let {core,onclose,invitation='',workspaceName='Основное'}:{core:Core;onclose:()=>void;invitation?:string;workspaceName?:string}=$props();
 let syncStatus=$state<SyncStatus>({phase:'idle',message:'',devices:[],conflicts:0,workspaces:[],selected:[],remoteWorkspaces:[],remoteSelected:[]}),mode=$state<'home'|'qr'|'scan'|'link'>('home'),qr=$state(''),link=$state(''),name=$state(''),error=$state(''),feedback=$state(''),busy=$state(false),differences=$state<SyncRecord[]>([]),selected=$state(''),editName=$state(false);
 let syncVisual=$state(false);
 let video=$state<HTMLVideoElement>();let showLink=$state(false);let scanner:QrScanner|undefined,alive=true,qrValue='';
 const storage=untrack(()=>core.storage as SQLiteAdapter);
 const session=deviceSync(untrack(()=>core));const unsubscribe=session.subscribe(value=>{syncStatus=value;if(value.invite)void makeQr(value.invite).catch(()=>error='Не удалось показать QR. Используйте ссылку подключения.');if(value.phase==='done')void refresh().catch(e=>error=e.message);});
 const connected=$derived(['verify','waiting','syncing','done','connecting'].includes(syncStatus.phase));
 const outgoing=$derived(syncStatus.workspaces.filter(w=>syncStatus.selected.includes(w.id)));
 const incoming=$derived(syncStatus.remoteWorkspaces.filter(w=>syncStatus.remoteSelected.includes(w.id)));
 const received=$derived(syncStatus.workspaces.filter(w=>incoming.some(remote=>remote.scope===w.scope)));
 async function openReceived(id:string){await storage.selectWorkspace(id);location.reload();}
 async function changeSelection(id:string,checked:boolean){await session.selectWorkspaces(checked?[...syncStatus.selected,id]:syncStatus.selected.filter(value=>value!==id));}
 async function chooseWorkspaces(){stopCamera();await session.reset();mode='home';feedback='Выберите хранилища и подключите устройство ещё раз. Новые хранилища потребуют согласия на втором экране.';}
 async function makeQr(value:string){
  if(qrValue===value&&qr)return;
  qrValue=value;
  const QR=await import('qrcode');
  const matrix=QR.create(value,{errorCorrectionLevel:'M'}).modules;
  const unit=10,quiet=4,canvas=document.createElement('canvas');
  canvas.width=canvas.height=(matrix.size+quiet*2)*unit;
  const ctx=canvas.getContext('2d');
  if(!ctx)throw Error('Не удалось нарисовать QR.');
  // Keep the quiet zone white and every module fully opaque: theme changes must
  // never turn an invitation into a low-contrast or inverted camera target.
  ctx.fillStyle='#ffffff';ctx.fillRect(0,0,canvas.width,canvas.height);
  ctx.fillStyle='#202327';
  const finders=[[0,0],[matrix.size-7,0],[0,matrix.size-7]];
  const finderAt=(x:number,y:number)=>finders.some(([fx,fy])=>x>=fx&&x<fx+7&&y>=fy&&y<fy+7);
  for(let y=0;y<matrix.size;y++)for(let x=0;x<matrix.size;x++){
   if(!matrix.get(y,x)||finderAt(x,y))continue;
   ctx.beginPath();ctx.roundRect((x+quiet)*unit,(y+quiet)*unit,unit,unit,unit*.2);ctx.fill();
  }
  for(const [x,y] of finders){
   const left=(x+quiet)*unit,top=(y+quiet)*unit;
   ctx.fillStyle='#202327';ctx.beginPath();ctx.roundRect(left,top,unit*7,unit*7,unit*.8);ctx.fill();
   ctx.fillStyle='#ffffff';ctx.beginPath();ctx.roundRect(left+unit,top+unit,unit*5,unit*5,unit*.35);ctx.fill();
   ctx.fillStyle='#202327';ctx.beginPath();ctx.roundRect(left+unit*2,top+unit*2,unit*3,unit*3,unit*.45);ctx.fill();
  }
  if(alive&&qrValue===value)qr=canvas.toDataURL('image/png');
 }
 async function refresh(){differences=await storage.syncConflicts();}
 async function run(action:()=>Promise<unknown>){busy=true;error='';try{await action();}catch(e){error=(e as Error).message;}finally{busy=false;}}
 async function connect(){const invite=parseInvitation(link.trim());stopCamera();await session.setName(name);await session.connect(invite);}
 async function copyLink(){try{await navigator.clipboard.writeText(syncStatus.invite!);feedback='Ссылка скопирована. Откройте её на своём втором устройстве.';}catch{showLink=true;feedback='Выделите и скопируйте ссылку ниже.';}}
 function stopCamera(){scanner?.destroy();scanner=undefined;}
 async function scan(){mode='scan';await tick();try{const {default:Qr}=await import('qr-scanner');if(!alive||mode!=='scan')return;scanner=new Qr(video!,result=>{link=result.data;stopCamera();mode='link';},{preferredCamera:'environment',maxScansPerSecond:8,highlightScanRegion:true});await scanner.start();}catch{stopCamera();error='Не удалось открыть камеру. Разрешите доступ в браузере, выберите изображение QR или вставьте ссылку.';mode='link';}}
 async function scanFile(file?:File){if(!file)return;const {default:Qr}=await import('qr-scanner');const result=await Qr.scanImage(file,{returnDetailedScanResult:true});parseInvitation(result.data);link=result.data;mode='link';}
 async function resolve(r:SyncRecord,choice:string){await storage.syncResolve(key(r),canonical(r),choice);await core.refresh();await session.refreshConflicts();await refresh();selected='';feedback='Версия сохранена. Синхронизируйте ещё раз, чтобы передать выбор.';}
 function recordTitle(r:SyncRecord){if(r.kind==='atom')return String((r.heads.find(h=>h.value)?.value as any)?.title||'Удалённая заметка');if(r.kind==='link')return 'Связь между заметками';if(r.kind==='catalog'||r.id==='plugin:builtin.templates:catalog')return 'Типы заметок';return ({preferences:'Общие настройки','appearance-profile':'Оформление','disabled-builtins':'Включённые плагины','community-plugins':'Сторонние плагины'} as Record<string,string>)[r.id]||'Настройки плагина: '+r.id.replace(/^plugin:/,'');}
 function describeVersion(v:any){return [({normal:'Обычные',now:'Сейчас',archived:'Архив',paused:'Пауза'} as Record<string,string>)[v.state],v.pinned?'Закреплена':'',`Важность: ${v.importance+1}`].filter(Boolean).join(' · ');}
 function linkTitle(v:any){const name=(id:string)=>core.data.atoms.find(a=>a.id===id)?.title||'Удалённая заметка';return `${name(v.from)} → ${name(v.to)}`;}
 onMount(()=>{void storage.syncGetGlobal<boolean>('sync:visual').then(value=>syncVisual=value===true);void storage.syncGetGlobal<string>('sync:device-name').then(value=>name=value||(/Android|iPhone|iPad/.test(navigator.userAgent)?'Телефон':'Компьютер'));if(invitation){mode='link';link=invitation;}void session.start();void refresh();});
 onDestroy(()=>{alive=false;stopCamera();unsubscribe();});
</script>
<div class="scrim" use:surface={{close:onclose}}><div class="editor settings device-sync" role="dialog" aria-modal="true" aria-label="Устройства и синхронизация" tabindex="-1">
 <div class="row sync-header"><div><h2>Ваши устройства</h2><p class="sync-help">Напрямую. Без облачного хранилища.</p></div><button aria-label="Закрыть синхронизацию" onclick={onclose}><svg viewBox="0 0 24 24"><path d="m6 6 12 12M18 6 6 18"/></svg></button></div>
 <div class="sync-body">
 <p class="sync-help">При открытом приложении изменения передаются автоматически. Выбранные хранилища остаются отдельными. Набор плагинов, их рабочие настройки и типы заметок общие для ваших устройств: нужные инструменты будут доступны на обоих.</p>
 <label class="workspace-option"><input type="checkbox" bind:checked={syncVisual} onchange={()=>run(()=>session.setVisual(syncVisual))}/><span>Синхронизировать оформление<small>Только для этого устройства. Выключено — тема, анимации и инструмент зума остаются своими. Заметки, папки, связи и рабочие плагины продолжают синхронизироваться.</small></span></label>
 {#if error}<p role="alert" class="inline-error">{error}</p>{/if}
 {#if feedback}<p role="status" class="sync-feedback">{feedback}</p>{/if}
 {#if !connected}
  <div class="device-name">{#if editName}<label>Название этого устройства<input aria-label="Название устройства" maxlength="80" bind:value={name} onblur={()=>run(async()=>{await session.setName(name);editName=false;})}/></label>{:else}<button class="name-button" onclick={()=>editName=true}><svg viewBox="0 0 24 24"><rect x="6" y="2" width="12" height="20" rx="3"/><path d="M10 18h4"/></svg><span>{name||'Это устройство'}<small>Название устройства</small></span><svg viewBox="0 0 24 24"><path d="m15 4 5 5M4 20l5-1L20 8l-5-5L4 14Z"/></svg></button>{/if}</div>
  {#if mode==='home'||mode==='link'}
   <fieldset class="workspace-picker"><legend>Передавать хранилища</legend><div class="workspace-summary"><span>{syncStatus.selected.length===syncStatus.workspaces.length?'Все хранилища':`Выбрано: ${syncStatus.selected.length}`}</span><button class="sync-text" disabled={busy||syncStatus.phase!=='ready'} onclick={()=>run(()=>session.selectWorkspaces(syncStatus.selected.length===syncStatus.workspaces.length?[]:syncStatus.workspaces.map(w=>w.id)))}>{syncStatus.selected.length===syncStatus.workspaces.length?'Снять выбор':'Выбрать все'}</button></div><div class="workspace-list">{#each syncStatus.workspaces as workspace (workspace.id)}<label class="workspace-option"><input type="checkbox" checked={syncStatus.selected.includes(workspace.id)} disabled={busy||syncStatus.phase!=='ready'} onchange={event=>run(()=>changeSelection(workspace.id,event.currentTarget.checked))}/><span>{workspace.name}<small>{workspace.hasData?'Есть записи':'Пустое хранилище'}</small></span></label>{/each}</div><p class="sync-help">На втором устройстве они появятся отдельно. Его записи тоже можно передать сюда.</p></fieldset>
  {/if}
  {#if mode==='home'}
   <div class="sync-choices"><button disabled={syncStatus.phase!=='ready'} onclick={()=>mode='qr'}><svg viewBox="0 0 24 24"><path d="M3 3h6v6H3zM15 3h6v6h-6zM3 15h6v6H3zM15 15h2v2h-2zM20 14v4h-2v3h3M13 21v-3M13 12h8M3 12h7"/></svg><span>Показать QR<small>Сканируйте другим устройством</small></span></button><button disabled={syncStatus.phase!=='ready'} onclick={()=>run(scan)}><svg viewBox="0 0 24 24"><path d="M3 8V3h5M16 3h5v5M21 16v5h-5M8 21H3v-5M4 12h16"/></svg><span>Сканировать QR<small>Камера этого устройства</small></span></button></div>
   <button class="sync-text" onclick={()=>mode='link'}>Подключиться по ссылке</button>
  {:else if mode==='qr'}
   <div class="qr-card"><div class="qr-heading"><h3>Продолжайте на другом устройстве</h3><p class="sync-help">Сканируйте код камерой телефона<br/>или внутри Phosphoreya.</p></div>{#if qr}<div class="qr-paper"><img src={qr} alt="QR для подключения своего устройства" width="250" height="250"/></div>{:else}<div class="qr-placeholder" role="status">Готовим код подключения…</div>{/if}<small>Личный код · действует 10 минут</small></div>
   <div class="sync-secondary"><button onclick={()=>run(copyLink)}>Скопировать ссылку</button><button onclick={()=>run(async()=>{qr='';showLink=false;await session.reset();})}>Новый QR</button></div>
   {#if showLink}<textarea aria-label="Ссылка для другого устройства" readonly rows="3" value={syncStatus.invite} onclick={e=>e.currentTarget.select()}></textarea>{/if}
  {:else if mode==='scan'}
   <div class="scan-frame"><video bind:this={video} autoplay playsinline muted aria-label="Камера для QR"></video></div><p class="sync-help">Наведите камеру на QR другого вашего устройства.</p>
  {:else}
   <label class="invite-input">Ссылка подключения<textarea aria-label="Ссылка подключения" rows="3" bind:value={link} placeholder="Вставьте ссылку с другого устройства" autocomplete="off" spellcheck="false"></textarea></label><button class="sync-primary" disabled={busy||syncStatus.phase!=='ready'||!link.trim()} onclick={()=>run(connect)}>Подключиться</button>
   <label class="sync-file">Выбрать изображение QR<input type="file" accept="image/*" onchange={e=>run(()=>scanFile(e.currentTarget.files?.[0]))}/></label>
  {/if}
  {#if mode!=='home'}<button class="sync-text" onclick={()=>{stopCamera();mode='home';error='';}}>Назад</button>{/if}
 {:else}
  <div class="peer-label"><svg viewBox="0 0 24 24"><path d="M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6ZM8 12l3 3 5-6"/></svg><span>{syncStatus.remoteName||'Другое ваше устройство'}</span></div>
  {#if syncStatus.phase==='verify'||syncStatus.phase==='waiting'}
   <div class="verification-heading"><h3>Одинаковые эмодзи?</h3><p class="sync-help">Сравните шесть знаков на обоих экранах, слева направо.</p></div><div class="verification-code" aria-label="Код проверки">{#each syncStatus.emojis||[] as emoji}<span>{emoji}</span>{/each}</div>
   <div class="exchange-summary"><div><span>С этого устройства</span><strong>{outgoing.map(w=>w.name).join(', ')||'Без передачи хранилищ'}</strong></div><div><span>Получать с другого устройства</span>{#each syncStatus.remoteWorkspaces.filter(w=>syncStatus.remoteOffered?.includes(w.id)) as workspace (workspace.id)}<label class="workspace-option"><input type="checkbox" checked={syncStatus.remoteSelected.includes(workspace.id)} disabled={syncStatus.phase!=='verify'} onchange={event=>run(()=>session.selectIncoming(event.currentTarget.checked?[...syncStatus.remoteSelected,workspace.id]:syncStatus.remoteSelected.filter(id=>id!==workspace.id)))}/><span>{workspace.name}</span></label>{/each}</div><p class="sync-help">Подтверждение разрешает также передачу установленных плагинов, их кода и разрешений. Соединяйте только свои устройства.</p></div>
   {#if syncStatus.phase==='verify'}<button class="sync-primary" disabled={busy} onclick={()=>run(()=>session.confirm())}>Да, совпадают</button><button class="sync-text" onclick={()=>run(()=>session.reset())}>Не совпадают — отменить</button>{:else}<p class="sync-help" role="status">{syncStatus.message}</p>{/if}
  {:else if syncStatus.phase==='done'}
   <div class="sync-success"><svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="9"/><path d="m8 12 3 3 5-6"/></svg><h3>{syncStatus.conflicts?'Есть разные версии':'Карты синхронизированы'}</h3><p class="sync-help" role="status">{syncStatus.message}</p></div>{#if received.length}<div class="exchange-summary"><span>Полученные хранилища</span>{#each received as workspace}<button onclick={()=>run(()=>openReceived(workspace.id))}>Открыть «{workspace.name}»</button>{/each}</div>{/if}<button class="sync-primary" onclick={onclose}>Готово</button><button disabled={busy} onclick={()=>run(()=>session.sync())}>Синхронизировать ещё раз</button><button class="sync-text" disabled={busy} onclick={()=>run(chooseWorkspaces)}>Изменить хранилища</button><p class="sync-help">Продолжайте на любом устройстве. Пока приложение открыто на обоих, изменения передаются автоматически.</p>
  {:else}<p class="sync-help" role="status">{syncStatus.message}</p>{#if syncStatus.phase==='syncing'}<progress aria-label="Передача карты" max="100" value={syncStatus.progress||0}></progress>{/if}{/if}
 {/if}
 {#if syncStatus.phase==='starting'||syncStatus.phase==='error'}<p class="sync-help" role="status">{syncStatus.message}</p>{/if}
 {#if syncStatus.phase==='error'}<button onclick={()=>run(()=>session.reset())}>Попробовать снова</button>{/if}
 {#if differences.length}<section class="sync-differences"><h3>Разные версии · {differences.length}</h3><p class="sync-help">Хранилище «{workspaceName}». Обе версии сохранены; выберите нужную или оставьте обе.</p>
  {#each differences as r (key(r))}<div class="sync-difference"><button class="difference-title" aria-expanded={selected===key(r)} onclick={()=>selected=selected===key(r)?'':key(r)}>{recordTitle(r)}<span>{r.heads.length} версии</span></button>
   {#if selected===key(r)}{#each r.heads as h}<article class="version-choice"><small>{h.device} · {new Date(h.at).toLocaleString('ru-RU')}</small>{#if h.value===null}<strong>Удалено на этом устройстве</strong>{:else if r.kind==='atom'}<strong>{(h.value as any).title}</strong><p class="sync-help">{describeVersion(h.value)}</p><pre>{(h.value as any).content||'Без текста'}</pre><details><summary>Оформление и другие свойства</summary><pre>{JSON.stringify({type:(h.value as any).type,appearance:(h.value as any).appearance,aliases:(h.value as any).aliases,properties:(h.value as any).properties,x:(h.value as any).x,y:(h.value as any).y},null,2)}</pre></details>{:else if r.kind==='link'}<strong>{linkTitle(h.value)}</strong>{:else}<strong>{recordTitle(r)}</strong><p class="sync-help">{Array.isArray(h.value)?h.value.map((type:any)=>type.name).join(' · '):'Настройки типов'}</p><details><summary>Технические подробности</summary><pre>{JSON.stringify(h.value,null,2)}</pre></details>{/if}<button disabled={busy} onclick={()=>run(()=>resolve(r,h.id))}>{h.value===null?'Подтвердить удаление':'Оставить эту версию'}</button></article>{/each}{#if r.kind==='atom'}<button class="sync-primary" disabled={busy} onclick={()=>run(()=>resolve(r,'both'))}>Сохранить обе отдельными заметками</button>{/if}{/if}
  </div>{/each}</section>{/if}
 {#if syncStatus.devices.length&&!connected}<section class="trusted-devices"><h3>Уже знакомы</h3>{#each syncStatus.devices as device}<div><button disabled={syncStatus.phase!=='ready'} onclick={()=>run(async()=>{await session.setName(name);session.reconnect(device);})}><svg viewBox="0 0 24 24"><path d="M4 4h16v12H4zM8 20h8M12 16v4"/></svg><span>{device.name||'Устройство'}<small>{device.lastSync?`Обмен: ${new Date(device.lastSync).toLocaleDateString('ru-RU')}`:'Подтверждено'}</small></span></button><button class="forget-device" aria-label={`Забыть ${device.name}`} onclick={()=>run(()=>session.forget(device.id))}><svg viewBox="0 0 24 24"><path d="m8 8 8 8M16 8l-8 8"/></svg></button></div>{/each}</section>{/if}
 <details class="sync-privacy"><summary>Как работает синхронизация</summary><p>QR содержит одноразовый секрет и отпечаток ключа. Сверьте эмодзи на двух экранах. Устройство с записями запрашивает подтверждение перед передачей; пустое принимает их без дополнительного нажатия. Известные устройства узнают друг друга по сохранённым ключам.</p><p>Вы выбираете хранилища для передачи. Расширение доступа требует нового согласия на другом устройстве. Передаются заметки, их координаты, связи, папки, задачи, типы заметок и общий профиль рабочих плагинов. Оформление принимается только с включённым переключателем выше. Ключи устройств, положение камеры, размер редактора, резервные копии и привязки к внешним файлам Obsidian остаются локальными.</p><p>Для соединения нужен интернет и служебный сервер PeerJS; заметки на нём не хранятся. Держите оба окна открытыми до окончания обмена. Это не шифрование базы на телефоне и не защита от вредоносного обновления приложения.</p></details>
</div></div></div>
<style>
 .device-sync{width:460px;gap:16px}.device-sync h2{margin:0}.device-sync h3{font-size:18px;font-weight:550;margin:10px 0}.device-sync p{margin:0}.sync-help,.sync-privacy p{font-size:13px;line-height:1.6;color:var(--theme-muted)}.device-name{display:grid;gap:7px;font-size:12px}.device-name input{width:100%;background:var(--theme-surfaceAlt);border-color:transparent}.sync-choices{display:grid;gap:8px}.sync-choices button,.trusted-devices>div>button:first-child{display:flex;align-items:center;gap:14px;text-align:left;background:var(--theme-surfaceAlt);border:0;padding:16px}.sync-choices span,.trusted-devices span{display:grid;gap:4px;font-size:14px}.sync-choices small,.trusted-devices small{font-size:11px;color:var(--theme-muted)}svg{width:22px;height:22px;flex:none;fill:none;stroke:currentColor;stroke-width:1.5;stroke-linecap:round;stroke-linejoin:round}.sync-text{background:transparent;border:0;color:var(--theme-muted);font-size:12px}.sync-primary{width:100%;background:var(--theme-text);color:var(--theme-surface);border:0;min-height:48px}.qr-card{display:grid;justify-items:center;gap:14px;text-align:center}.qr-card img{width:min(250px,100%);height:auto;border-radius:18px;background:#fff}.qr-card p{font-size:12px;line-height:1.55}.qr-card small{font-size:10px;color:var(--theme-muted)}.sync-secondary{display:flex;justify-content:center;gap:8px}.sync-secondary button{font-size:12px;flex:1;padding:10px}.scan-frame{border-radius:20px;overflow:hidden;background:var(--theme-background);aspect-ratio:1}.scan-frame video{display:block;width:100%;height:100%;object-fit:cover}.invite-input{display:grid;gap:8px}.invite-input textarea{width:100%;font-size:12px;resize:vertical;overflow-wrap:anywhere}.sync-file{position:relative;display:flex;justify-content:center;min-height:44px;align-items:center;font-size:12px;color:var(--theme-muted);overflow:hidden}.sync-file input{position:absolute;inset:0;opacity:0;width:100%;cursor:pointer}.peer-label{display:flex;align-items:center;gap:8px;